  toggleMute() {
    this.enabled = !this.enabled;
    if (this.initialized && this.masterGain) {
      const target = (this.enabled && !this.simPaused) ? 0.62 : 0.0;
      this.masterGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.05);
    }
    if (!this.enabled) {
      this.cancelAnnouncements();
    }
    return this.enabled;
  }
  setSimPaused(paused) {
    this.simPaused = Boolean(paused);
    if (this.initialized && this.masterGain) {
      const target = (this.enabled && !this.simPaused) ? 0.62 : 0.0;
      this.masterGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.04);
    }
  }
  cancelAnnouncements() {
    for (const id of this._paTimeouts) clearTimeout(id);
    this._paTimeouts = [];
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      try {
        window.speechSynthesis.cancel();
      } catch (_e) {
      }
    }
  }
