  playKomodoArmorSweep(isDarkening = true, numCars = 8) {
    if (!this.enabled) return;
    this.init();
    if (!this.initialized) return;
    const now = this.ctx.currentTime;
    const count = Math.max(4, Math.min(16, numCars || 8));
    const totalDur = 1.08;
    const sweepOsc = this.ctx.createOscillator();
    sweepOsc.type = 'sawtooth';
    sweepOsc.frequency.setValueAtTime(isDarkening ? 132.0 : 54.0, now);
    sweepOsc.frequency.exponentialRampToValueAtTime(isDarkening ? 44.0 : 142.0, now + totalDur);
    const sweepFilt = this.ctx.createBiquadFilter();
    sweepFilt.type = 'lowpass';
    sweepFilt.Q.value = 3.2;
    sweepFilt.frequency.setValueAtTime(isDarkening ? 920.0 : 340.0, now);
    sweepFilt.frequency.exponentialRampToValueAtTime(isDarkening ? 220.0 : 980.0, now + totalDur);
    const sweepGain = this.ctx.createGain();
    sweepGain.gain.setValueAtTime(0.0008, now);
    sweepGain.gain.linearRampToValueAtTime(0.068, now + 0.09);
    sweepGain.gain.setValueAtTime(0.062, now + totalDur * 0.78);
    sweepGain.gain.exponentialRampToValueAtTime(0.0006, now + totalDur + 0.14);
    sweepOsc.connect(sweepFilt);
    sweepFilt.connect(sweepGain);
    sweepGain.connect(this.masterGain);
    sweepOsc.start(now);
    sweepOsc.stop(now + totalDur + 0.16);
    for (let i = 0; i < count; i++) {
      const u = i / Math.max(1, count - 1);
      const tCar = now + u * (totalDur * 0.92);
      const clickOsc = this.ctx.createOscillator();
      clickOsc.type = 'triangle';
      const baseHz = isDarkening ? (1680.0 - u * 620.0) : (980.0 + u * 640.0);
      clickOsc.frequency.setValueAtTime(baseHz, tCar);
      clickOsc.frequency.exponentialRampToValueAtTime(baseHz * 0.42, tCar + 0.065);
      const clickGain = this.ctx.createGain();
      const atten = 1.0 - u * 0.38;
      clickGain.gain.setValueAtTime(0.0006, tCar);
      clickGain.gain.linearRampToValueAtTime(0.044 * atten, tCar + 0.008);
      clickGain.gain.exponentialRampToValueAtTime(0.0005, tCar + 0.075);
      if (typeof this.ctx.createStereoPanner === 'function') {
        const pan = this.ctx.createStereoPanner();
        pan.pan.setValueAtTime(-0.42 + u * 0.84, tCar);
        clickOsc.connect(clickGain);
        clickGain.connect(pan);
        pan.connect(this.masterGain);
      } else {
        clickOsc.connect(clickGain);
        clickGain.connect(this.masterGain);
      }
      clickOsc.start(tCar);
      clickOsc.stop(tCar + 0.085);
    }
  }
