  _ensureKomodoArmorUniforms() {
    if (!this._komodoArmorUniforms) {
      this._komodoArmorUniforms = {
        uKomodoWavePos: { value: -25.0 },
        uKomodoSpanM: { value: 209.0 },
        uKomodoFromState: { value: 0.0 },
        uKomodoToState: { value: 0.0 },
        uKomodoWaveActive: { value: 0.0 },
        uKomodoFrontPos: { value: new THREE.Vector3(0, 0, 0) },
        uKomodoAxisVec: { value: new THREE.Vector3(0, 0, 1) }
      };
      this._komodoArmorCurrent = 0.0;
      this._komodoWaveTimer = -1.0;
      this._komodoWaveDuration = 1.08;
    }
    return this._komodoArmorUniforms;
  }
  triggerKomodoArmorWave(toDark = true) {
    const u = this._ensureKomodoArmorUniforms();
    const target = toDark ? 1.0 : 0.0;
    if (
      this._komodoWaveTimer < 0 &&
      Math.abs(this._komodoArmorCurrent - target) < 0.01 &&
      Math.abs(u.uKomodoToState.value - target) < 0.01
    ) {
      return;
    }
    u.uKomodoFromState.value = this._komodoArmorCurrent;
    u.uKomodoToState.value = target;
    u.uKomodoWavePos.value = -4.5;
    u.uKomodoWaveActive.value = 1.0;
    this._komodoWaveDuration = 1.08;
    this._komodoWaveTimer = 0.0;
  }
  _attachKomodoArmorShader(mat, keySuffix, includeFairingAlloy = false) {
    const u = this._ensureKomodoArmorUniforms();
    const alloyFlag = includeFairingAlloy ? '1.0' : '0.0';
    mat.customProgramCacheKey = () => 'komodoArmorV2_' + keySuffix + (includeFairingAlloy ? '_alloy' : '');
    mat.onBeforeCompile = (shader) => {
      shader.uniforms.uKomodoWavePos = u.uKomodoWavePos;
      shader.uniforms.uKomodoSpanM = u.uKomodoSpanM;
      shader.uniforms.uKomodoFromState = u.uKomodoFromState;
      shader.uniforms.uKomodoToState = u.uKomodoToState;
      shader.uniforms.uKomodoWaveActive = u.uKomodoWaveActive;
      shader.uniforms.uKomodoFrontPos = u.uKomodoFrontPos;
      shader.uniforms.uKomodoAxisVec = u.uKomodoAxisVec;
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'uniform vec3 uKomodoFrontPos;',
            'uniform vec3 uKomodoAxisVec;',
            'varying float vKomodoLongM;',
            'varying vec3 vKomodoLocalPos;'
          ].join('\n')
        )
        .replace(
          '#include <worldpos_vertex>',
          [
            '#include <worldpos_vertex>',
            '#ifdef USE_INSTANCING',
            '  vec4 komodoWp = modelMatrix * instanceMatrix * vec4(transformed, 1.0);',
            '#else',
            '  vec4 komodoWp = modelMatrix * vec4(transformed, 1.0);',
            '#endif',
            'vKomodoLongM = dot(komodoWp.xyz - uKomodoFrontPos, uKomodoAxisVec);',
            'vKomodoLocalPos = transformed;'
          ].join('\n')
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'uniform float uKomodoWavePos;',
            'uniform float uKomodoFromState;',
            'uniform float uKomodoToState;',
            'uniform float uKomodoWaveActive;',
            'varying float vKomodoLongM;',
            'varying vec3 vKomodoLocalPos;'
          ].join('\n')
        )
        .replace(
          '#include <color_fragment>',
          [
            '#include <color_fragment>',
            'float komodoRedDom = diffuseColor.r - max(diffuseColor.g * 2.6, diffuseColor.b * 2.15);',
            'float komodoRedMask = smoothstep(0.035, 0.135, komodoRedDom);',
            'float komodoPeakLuma = max(diffuseColor.r, max(diffuseColor.g, diffuseColor.b));',
            'float komodoAlloyMask = (' + alloyFlag + ') * (1.0 - komodoRedMask) * smoothstep(0.08, 0.28, komodoPeakLuma);',
            'float komodoTotalMask = clamp(komodoRedMask + komodoAlloyMask, 0.0, 1.0);',
            'float komodoSlantM = vKomodoLongM - vKomodoLocalPos.y * 0.85;',
            'float komodoSegM = floor(komodoSlantM / 1.32) * 1.32;',
            'float komodoScaleU = komodoSlantM * 3.35 + vKomodoLocalPos.y * 5.15;',
            'float komodoScaleV = komodoSlantM * 3.35 - vKomodoLocalPos.y * 5.15;',
            'float komodoScaleHash = fract(sin(floor(komodoScaleU) * 127.1 + floor(komodoScaleV) * 311.7) * 43758.5453);',
            'float komodoMechCoord = komodoSlantM + (komodoSegM - komodoSlantM) * 0.48 + (komodoScaleHash - 0.5) * 1.75;',
            'float komodoWaveSweep = smoothstep(-2.8, 2.2, uKomodoWavePos - komodoMechCoord);',
            'float komodoStateNow = mix(uKomodoFromState, uKomodoToState, komodoWaveSweep);',
            'float komodoArmorAmt = komodoStateNow * komodoTotalMask;',
            'float komodoFacetShade = 0.86 + 0.26 * komodoScaleHash;',
            'vec3 komodoCrimsonTint = vec3(diffuseColor.r * 0.185, diffuseColor.g * 0.125, diffuseColor.b * 0.165) * komodoFacetShade;',
            'vec3 komodoAlloyTint = vec3(diffuseColor.r * 0.21, diffuseColor.g * 0.23, diffuseColor.b * 0.28) * (0.90 + 0.18 * komodoScaleHash);',
            'vec3 komodoTargetTint = mix(komodoAlloyTint, komodoCrimsonTint, komodoRedMask);',
            'diffuseColor.rgb = mix(diffuseColor.rgb, komodoTargetTint, komodoArmorAmt);',
            'float komodoWaveDist = komodoMechCoord - uKomodoWavePos;',
            'float komodoLeadSeam = exp(-pow(komodoWaveDist / 0.78, 2.0));',
            'float komodoTrailWake = exp(-pow((komodoWaveDist + 1.65) / 2.25, 2.0));',
            'float komodoScaleEdge = 1.0 - smoothstep(0.0, 0.16, min(abs(fract(komodoScaleU) - 0.5), abs(fract(komodoScaleV) - 0.5)));',
            'float komodoSegSeam = 1.0 - smoothstep(0.0, 0.08, abs(fract(komodoSlantM / 1.32) - 0.5));',
            'float komodoWaveGlow = uKomodoWaveActive * (komodoRedMask + komodoAlloyMask * 0.65) * (komodoLeadSeam * 0.92 + komodoTrailWake * max(komodoScaleEdge * 0.72, komodoSegSeam * 0.85));'
          ].join('\n')
        )
        .replace(
          '#include <roughnessmap_fragment>',
          [
            '#include <roughnessmap_fragment>',
            'roughnessFactor = mix(roughnessFactor, max(0.06, roughnessFactor * 0.64), komodoArmorAmt * 0.88);'
          ].join('\n')
        )
        .replace(
          '#include <emissivemap_fragment>',
          [
            '#include <emissivemap_fragment>',
            'totalEmissiveRadiance += vec3(1.65, 0.28, 0.06) * komodoWaveGlow;'
          ].join('\n')
        );
    };
  }
