  applyOriginRebase(deltaX, deltaY = 0, deltaZ = 0) {
    for (const s of this.sparkPool) {
      if (s.life > 0) {
        s.mesh.position.x += deltaX;
        s.mesh.position.y += deltaY;
        s.mesh.position.z += deltaZ;
        s.floorY += deltaY;
      }
    }
    if (this.sandPool) {
      for (const p of this.sandPool) {
        if (p.life > 0) {
          p.mesh.position.x += deltaX;
          p.mesh.position.y += deltaY;
          p.mesh.position.z += deltaZ;
        }
      }
    }
    if (this.rocketSmokePool) {
      for (let i = 0; i < this.rocketSmokePool.length; i++) {
        const sm = this.rocketSmokePool[i];
        if (sm.life > 0) {
          sm.wx += deltaX;
          sm.wy += deltaY;
          sm.wz += deltaZ;
          if (sm.floorY > -500.0) sm.floorY += deltaY;
        }
      }
    }
    if (this.railThermalPool) {
      for (let i = 0; i < this.railThermalPool.length; i++) {
        const rt = this.railThermalPool[i];
        if (rt.life > 0) {
          rt.wx += deltaX;
          rt.wy += deltaY;
          rt.wz += deltaZ;
        }
      }
    }
  }
