        podHost,
        doorUp,
        doorLow,
        upBaseX: upPetal.hx,
        lowBaseX: lowPetal.hx,
        fwdLouvre,
        ramUp,
        ramLow,
        rPod,
        nozzleCarriage,
        bellGlow,
        throatGlow,
        plumeRoot,
        outerJet,
        coreJet,
        flashDisc,
        rDiamonds,
