        pod.intakeCone.position.z = pod.intakeBaseZ + pod.intakeDeployOffsetZ * spikeExtend;
        const checkPitch = inTvcCheck ? Math.sin(tvcPhase) * 0.12 : 0.0;
        const checkYaw = inTvcCheck ? Math.sin(tvcPhase * 2.0) * 0.08 * sgn : 0.0;
        const liveTvcPitch = -THREE.MathUtils.clamp((this.liveAccelMps2 || 0.0) * 0.010, -0.04, 0.04) * pc;
