    ctx.fillRect(25, 25, 10, 14);
    ctx.fillRect(21, 39, 7, 11);
    ctx.fillRect(32, 37, 8, 9);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 17px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('KELUAR • EXIT ➔', 148, 30);
    ctx.fillStyle = '#a7f3d0';
    ctx.font = 'bold 12.5px sans-serif';
    ctx.fillText('JALUR EVAKUASI • BORDES', 148, 50);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.exitSignMat = new THREE.MeshBasicMaterial({ map: tex });
    return this.exitSignMat;
