        vertexColors: true,
        metalness: 0.04,
        roughness: 0.05,
        clearcoat: 0.90,
        clearcoatRoughness: 0.06,
        envMapIntensity: 0.55,
        transparent: true,
        opacity: 0.04,
        depthWrite: false
