    const tSinceDep = Number.isFinite(this.cabinTimeSinceDepartSec) ? this.cabinTimeSinceDepartSec : 0.0;
    const atStationStop = Boolean(this.doorsOpen || (spdNowKmh < 12.0 && distToNextSt < 260.0));
    const cruiseCycle = ((tSec % 220.0) + 220.0) % 220.0;
    let scenarioPhase = 'SERENE_CRUISE_CLEAR_AISLE';
