    const terminusName = this.travelDir >= 0 ? 'Tegalluar Summarecon' : 'Halim';
    const nextName = (stationObj && stationObj.shortName) || (this.travelDir >= 0 ? 'Padalarang' : 'Halim');
    let idText = '';
