        const thrErr = rawTargetThr - this.actualThrottlePct;
        const thrAcc = THREE.MathUtils.clamp(wnThr * wnThr * thrErr - 2.0 * wnThr * this.actualThrottleRate, -95.0, this.maglevLevel >= 3 ? 380.0 : (this.maglevMode ? 220.0 : 80.0));
        this.actualThrottleRate = THREE.MathUtils.clamp(this.actualThrottleRate + thrAcc * subDt, -68.0, this.maglevLevel >= 3 ? 140.0 : (this.maglevMode ? 84.0 : 26.0));
