            const lsmBasePowerW = 152.0e6 * carMult;
            const lsmForceN = (this.actualThrottlePct / 100.0) * Math.min(lsmBaseForceN, lsmBasePowerW / Math.max(absV, 30.0));
            const rocketThrustFrac = THREE.MathUtils.clamp((this.rocketChamberPressure - 0.078) / 0.922, 0.0, 1.0);
