  evaluateStationStop(dt) {
    const { station } = EndlessWorldMathematics.getNearestStationInfo(this.distanceS);
    if (station.isDepot) return;
    const isSkippedByExpress = (this.serviceMode === 'EXPRESS' && station.id === 'KARAWANG');
    const stopS = this.getStationStopS(station);
    const errM = (this.distanceS - stopS) * (this.travelDir >= 0 ? 1 : -1);
    const dockPanel = document.getElementById('docking-guide-panel');
    if (!isSkippedByExpress && Math.abs(errM) < 180 && Math.abs(this.speedMps) < 28.0) {
      dockPanel.classList.remove('hidden');
      dockPanel.classList.add('flex');
      const sign = errM >= 0 ? '+' : '';
      document.getElementById('docking-dist-readout').textContent = `${sign}${errM.toFixed(2)} m`;
      const pct = THREE.MathUtils.clamp(50 + (errM / 60) * 45, 4, 96);
      document.getElementById('docking-nose-marker').style.left = `${pct}%`;
    } else {
      dockPanel.classList.add('hidden');
      dockPanel.classList.remove('flex');
    }
    const dir = this.travelDir >= 0 ? 1 : -1;
    const isTerminusStop = (dir > 0 && station.id === 'TEGALLUAR') || (dir < 0 && station.id === 'HALIM');
    const earlyBtn = document.getElementById('btn-depart-early');
    if (!isSkippedByExpress && Math.abs(this.speedMps) < 0.08 && Math.abs(errM) < 45 && !this.evaluatedStopIds.has(station.id)) {
      this.evaluatedStopIds.add(station.id);
      const dwellSec = this.getStationScheduledDwellSec(station);
      this.activeDwellStationId = station.id;
      this.stationDwellTotalSec = dwellSec;
      this.stationDwellRemainingSec = dwellSec;
      this.boardingProgress = dwellSec > 0 ? 0 : 100;
      if (isTerminusStop) {
        this.completedStationIds.add(station.id);
      }
      const absE = Math.abs(errM);
      let grade = 'B GOOD';
      let pts = 750;
      if (absE <= 0.30) { grade = 'S+ PRESISI PERON!'; pts = 2500; }
      else if (absE <= 0.75) { grade = 'S MASTER'; pts = 2000; }
      else if (absE <= 2.5) { grade = 'A EXCELLENT'; pts = 1400; }
      this.score += pts;
      this.audio.playChime('STATION');
      document.getElementById('eval-st-name').textContent = `${station.name} (${station.dkLabel})`;
      document.getElementById('eval-rank-pill').textContent = grade;
      document.getElementById('eval-err-m').textContent = `${errM >= 0 ? '+' : ''}${errM.toFixed(2)} m`;
      document.getElementById('eval-time-bonus').textContent = formatDurationClock(this.tripElapsedSec);
      document.getElementById('eval-comfort-score').textContent = `${Math.round(this.comfort)}%`;
      document.getElementById('eval-pts-earned').textContent = `+${pts.toLocaleString()}`;
      document.getElementById('eval-boarding-progress').style.width = `${Math.round(this.boardingProgress)}%`;
      document.getElementById('station-eval-modal').classList.remove('hidden');
      if (earlyBtn) earlyBtn.classList.toggle('hidden', !(dwellSec > 0));
      if (!this.train.doorsOpen && dwellSec > 0) {
        const dwellMinLbl = Math.round(dwellSec / 60);
        document.getElementById('eval-boarding-status').innerHTML =
          `<i class="ph-fill ph-door-open text-amber-400 text-base"></i><span>Buka pintu <strong>[DOORS / O]</strong> untuk mulai henti GAPEKA ${dwellMinLbl} menit (${formatDurationClock(dwellSec)}).</span>`;
      }
    } else if (Math.abs(errM) > 65 && Math.abs(this.speedMps) > 2.5) {
      if (this.activeDwellStationId === station.id) {
        this.completedStationIds.add(station.id);
        this.activeDwellStationId = null;
      }
      document.getElementById('station-eval-modal').classList.add('hidden');
      if (earlyBtn) earlyBtn.classList.add('hidden');
    } else if (
      this.activeDwellStationId === station.id &&
      !this.train.doorsOpen &&
      (this.stationDwellRemainingSec <= 0 || Math.abs(this.speedMps) > 0.9)
    ) {
      this.completedStationIds.add(station.id);
    }
    const evalModal = document.getElementById('station-eval-modal');
    if (evalModal && !evalModal.classList.contains('hidden')) {
      if (isTerminusStop && this.evaluatedStopIds.has(station.id)) {
        this.boardingProgress = 100;
        document.getElementById('eval-boarding-progress').style.width = '100%';
        if (earlyBtn) earlyBtn.classList.add('hidden');
        document.getElementById('eval-boarding-status').innerHTML =
          `<i class="ph-fill ph-flag-checkered text-emerald-400 text-base"></i><span>Tiba di Stasiun Akhir ${station.shortName}! Seluruh penumpang turun ke peron KCIC.</span>`;
      } else if (this.train.doorsOpen) {
        if (this.stationDwellTotalSec > 0) {
          this.stationDwellRemainingSec = Math.max(0.0, this.stationDwellRemainingSec - dt);
          this.boardingProgress = THREE.MathUtils.clamp(
            ((this.stationDwellTotalSec - this.stationDwellRemainingSec) / this.stationDwellTotalSec) * 100.0,
            0.0,
            100.0
          );
        } else {
          this.boardingProgress = Math.min(100, this.boardingProgress + dt * 13.5);
        }
        document.getElementById('eval-boarding-progress').style.width = `${Math.round(this.boardingProgress)}%`;
        if (earlyBtn) {
          earlyBtn.classList.toggle('hidden', !(this.stationDwellTotalSec > 0 && this.stationDwellRemainingSec > 0.2));
        }
        const remClock = formatDurationClock(Math.ceil(this.stationDwellRemainingSec));
        const totClock = formatDurationClock(this.stationDwellTotalSec);
        if (this.stationDwellRemainingSec > 0.05) {
          if (station.id === 'PADALARANG') {
            if (this.boardingProgress < 38) {
              document.getElementById('eval-boarding-status').innerHTML =
                `<i class="ph-fill ph-users-three text-amber-400 text-base"></i><span>Turun &amp; transit KA Feeder Bandung • Henti GAPEKA: <strong>${remClock}</strong> / ${totClock}</span>`;
            } else if (this.boardingProgress < 84) {
              document.getElementById('eval-boarding-status').innerHTML =
                `<i class="ph-fill ph-train text-cyan-400 text-base"></i><span>Penumpang KA Feeder naik ke Whoosh • Henti GAPEKA: <strong>${remClock}</strong> / ${totClock}</span>`;
            } else {
              document.getElementById('eval-boarding-status').innerHTML =
                `<i class="ph-fill ph-shield-check text-sky-400 text-base"></i><span>Cek akhir batas aman peron &amp; pintu • Henti GAPEKA: <strong>${remClock}</strong> / ${totClock}</span>`;
            }
          } else {
            document.getElementById('eval-boarding-status').innerHTML =
              `<i class="ph-fill ph-users-three text-cyan-400 text-base"></i><span>Pertukaran penumpang ${station.shortName} • Sisa Henti GAPEKA: <strong>${remClock}</strong> / ${totClock}</span>`;
          }
        } else {
          const minDone = Math.max(1, Math.round(this.stationDwellTotalSec / 60));
          document.getElementById('eval-boarding-status').innerHTML =
            `<i class="ph-fill ph-check-circle text-emerald-400 text-base"></i><span>Henti GAPEKA ${minDone} menit selesai (100%)! Tutup <strong>[DOORS / O]</strong>, klakson <strong>[SPACE]</strong> &amp; jalan.</span>`;
        }
      }
    }
  }
