    const btnCoachDim = document.getElementById('btn-coach-dim');
    const btnCoachLamp = document.getElementById('btn-coach-lamp');
    const btnCoachCoin = document.getElementById('btn-coach-coin');
    const btnCoachSafety = document.getElementById('btn-coach-safety');
