    if (btnCoachFootrest) btnCoachFootrest.addEventListener('click', () => this.triggerCoachErgonomicAction('FOOTREST'));
    if (btnCoachCoat) btnCoachCoat.addEventListener('click', () => this.triggerCoachErgonomicAction('COAT_HOOK'));
    if (btnCoachRotate) btnCoachRotate.addEventListener('click', () => this.triggerCoachErgonomicAction('ROTATE_SEAT'));
