    if (btnCoachLamp) btnCoachLamp.addEventListener('click', () => this.triggerCoachErgonomicAction('READING_LAMP'));
    if (btnCoachCoin) btnCoachCoin.addEventListener('click', () => this.triggerCoachErgonomicAction('COIN_TEST'));
    if (btnCoachSafety) btnCoachSafety.addEventListener('click', () => this.triggerCoachErgonomicAction('SAFETY_CARD'));
    if (btnCoachMag) btnCoachMag.addEventListener('click', () => this.triggerCoachErgonomicAction('MAGAZINE'));
    if (btnCoachMerch) btnCoachMerch.addEventListener('click', () => this.triggerCoachErgonomicAction('MERCH_SOUVENIR'));
    if (btnCoachAnc) btnCoachAnc.addEventListener('click', () => this.triggerCoachErgonomicAction('ANC_HEADSET'));
    if (btnCoachIfe) btnCoachIfe.addEventListener('click', () => this.triggerCoachErgonomicAction('IFE_SCREEN'));
